function generateAndSolveMaze(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) {
        console.error("Canvas not found");
        return;
    }
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const cols = width / cellSize;
    const rows = height / cellSize;

    let maze = Array.from({ length: rows }, () => Array(cols).fill(0));
    let openSet = [];
    let closedSet = [];
    let startNode, endNode;

    function drawMaze() {
        for (let i = 0; i < rows; i++) {
            for (let j = 0; j < cols; j++) {
                if (maze[i][j] === 1) {
                    ctx.fillStyle = 'black';
                    ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
                } else {
                    ctx.fillStyle = 'white';
                    ctx.fillRect(j * cellSize, i * cellSize, cellSize, cellSize);
                }
            }
        }
    }

    function recursiveDivision(x, y, w, h) {
        if (w <= 1 || h <= 1) return;

        let horizontal = Math.random() > 0.5 && w > 2 ? true : false;
        let vertical = !horizontal && h > 2 ? true : false;

        if (horizontal) {
            let wx = x + Math.floor(Math.random() * (w - 1)) * cellSize;
            let px = wx + cellSize;
            let py = y + Math.floor(Math.random() * h) * cellSize;

            for (let i = y; i < y + h; i += cellSize) {
                maze[px / cellSize][i / cellSize] = 1;
            }

            recursiveDivision(x, y, w, py - y);
            recursiveDivision(x, py + cellSize, w, y + h - py - cellSize);
        } else {
            let wy = y + Math.floor(Math.random() * (h - 1)) * cellSize;
            let py = wy + cellSize;
            let px = x + Math.floor(Math.random() * w) * cellSize;

            for (let i = x; i < x + w; i += cellSize) {
                maze[i / cellSize][py / cellSize] = 1;
            }

            recursiveDivision(x, y, px - x, h);
            recursiveDivision(px + cellSize, y, x + w - px - cellSize, h);
        }
    }

    function aStarSearch() {
        openSet.push(startNode);
        while (openSet.length > 0) {
            let current = openSet.reduce((prev, curr) => prev.f < curr.f ? prev : curr);

            if (current === endNode) {
                reconstructPath(current);
                return;
            }

            openSet.splice(openSet.indexOf(current), 1);
            closedSet.push(current);

            let neighbors = getNeighbors(current);
            for (let neighbor of neighbors) {
                if (closedSet.includes(neighbor)) continue;

                let tentativeGScore = current.g + 1;
                if (!openSet.includes(neighbor)) {
                    openSet.push(neighbor);
                } else if (tentativeGScore >= neighbor.g) continue;

                neighbor.parent = current;
                neighbor.g = tentativeGScore;
                neighbor.h = heuristic(neighbor, endNode);
                neighbor.f = neighbor.g + neighbor.h;
            }
        }
    }

    function getNeighbors(node) {
        let neighbors = [];
        let [x, y] = node.position;
        if (x > 0 && maze[y / cellSize][x / cellSize - 1] !== 1) neighbors.push({ position: [x - cellSize, y], g: Infinity, h: Infinity, f: Infinity });
        if (x < width - cellSize && maze[y / cellSize][x / cellSize + 1] !== 1) neighbors.push({ position: [x + cellSize, y], g: Infinity, h: Infinity, f: Infinity });
        if (y > 0 && maze[y / cellSize - 1][x / cellSize] !== 1) neighbors.push({ position: [x, y - cellSize], g: Infinity, h: Infinity, f: Infinity });
        if (y < height - cellSize && maze[y / cellSize + 1][x / cellSize] !== 1) neighbors.push({ position: [x, y + cellSize], g: Infinity, h: Infinity, f: Infinity });
        return neighbors;
    }

    function heuristic(a, b) {
        return Math.abs(a.position[0] - b.position[0]) + Math.abs(a.position[1] - b.position[1]);
    }

    function reconstructPath(node) {
        let path = [];
        while (node.parent) {
            path.unshift(node);
            node = node.parent;
        }
        path.unshift(startNode);
        path.push(endNode);

        for (let i = 0; i < path.length; i++) {
            let [x, y] = path[i].position;
            ctx.fillStyle = 'green';
            ctx.fillRect(x, y, cellSize, cellSize);
        }
    }

    function createNodes() {
        for (let i = 0; i < rows; i++) {
            for (let j = 0; j < cols; j++) {
                if (maze[i][j] === 0) {
                    maze[i][j] = { position: [j * cellSize, i * cellSize], g: Infinity, h: Infinity, f: Infinity };
                }
            }
        }
        startNode = maze[0][0];
        endNode = maze[rows - 1][cols - 1];
    }

    function visualizeStep() {
        drawMaze();
        // Add visualization logic for A* search here
        requestAnimationFrame(visualizeStep);
    }

    recursiveDivision(0, 0, width, height);
    createNodes();
    visualizeStep();
    aStarSearch();
}
